head.script:
scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성 (createBasicMultiSelect 로 동적 생성, invalidMessage 속성 적용)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // gdl_multiselect 재생성 (idempotent: 기존 dataList 제거 후 재생성)
    $c.gcm.createDataListMultiSelect();

    // 조건 설정
    let properties = {
        displaymessage: true,
        mandatory: true,
        invalidMessage: wf_sample.getObj("con_invalidMessage").getValue(),
        invalidMessageFunc: wf_sample.getObj("con_invalidMessageFunc").getText(),
    };

    let cList = $c.gcm.createCList(properties);

    $c.gcm.createBasicMultiSelect(cList);
}
